INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('ABBV','published','{"ticker":"ABBV","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://news.abbvie.com/","description":"Biopharmaceutical company with immunology, oncology, neuroscience, eye care, aesthetics, and other specialty franchises.","lede":"AbbVie''s thesis depends on Skyrizi and Rinvoq replacing Humira while neuroscience, oncology, and aesthetics diversify cash flow and acquisitions earn acceptable returns.","sells":"Prescription medicines across immunology, oncology, neuroscience, eye care, and other specialties plus medical-aesthetics products.","revenueModel":"Patent-protected product sales through wholesalers, pharmacies, providers, and payers, net of rebates, discounts, and returns.","opportunity":"New immunology indications, neuroscience growth, oncology innovation, and global penetration can extend the portfolio beyond legacy concentration.","mustGoRight":"Skyrizi and Rinvoq must sustain differentiation, pipeline and acquired assets must deliver, aesthetics must remain resilient, and leverage and patent losses must be managed.","editorNote":"Build a product-level bridge from Humira erosion to replacement-franchise revenue and cash flow, including rebates, R&D, milestones, and acquisition financing.","bullTitle":"What can compound owner value","bull":["Skyrizi and Rinvoq provide differentiated immunology growth across indications.","Neuroscience and aesthetics diversify the portfolio.","Large cash flows fund pipeline development and debt reduction.","Commercial scale can accelerate acquired assets."],"bearTitle":"What can impair the thesis","bear":["Portfolio concentration remains meaningful despite Humira transition.","Safety, payer, or competitive changes can weaken immunology growth.","Acquisitions add leverage and pipeline execution risk.","Patent losses and biosimilars create recurring replacement needs."],"thesisBreaker":"The thesis breaks if replacement immunology franchises lose clinical or payer momentum and acquired pipeline assets fail to offset patent erosion and financing costs.","financialDrivers":[{"label":"IMMUNOLOGY","value":"Replacement growth","detail":"Skyrizi and Rinvoq volume, indications, net price, share, and safety"},{"label":"NEUROSCIENCE","value":"Diversification","detail":"Prescription growth, launches, payer access, and acquired assets"},{"label":"AESTHETICS","value":"Consumer cycle","detail":"Procedure demand, provider inventory, competition, and pricing"},{"label":"PIPELINE / DEALS","value":"Future value","detail":"Readouts, approvals, milestones, integration, and return on invested capital"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Product concentration","level":"High","text":"A few franchises drive a large portion of growth and cash.","signal":"Product-level sales, share, indications, and patent timelines"},{"title":"Clinical and safety","level":"High","text":"Adverse results or warnings can restrict major products.","signal":"Trials, labels, discontinuation, and adverse events"},{"title":"Acquisition leverage","level":"Medium","text":"Deals can overpay for uncertain pipeline value.","signal":"Debt, milestones, impairments, synergy delivery, and asset performance"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Humira replacement bridge","text":"Track replacement growth net of legacy erosion and rebates.","impact":"BULL CASE"},{"title":"Pipeline diversification","text":"Measure probability-adjusted value outside immunology.","impact":"NEUTRAL"},{"title":"Deal returns","text":"Compare acquired cash flows with price, financing, and dilution.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["How concentrated is long-term value in Skyrizi and Rinvoq?","Which acquired programs carry the greatest risk-adjusted value?","How should aesthetics be normalized through a consumer cycle?","What patent and payer events create the next replacement gap?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Johnson & Johnson, Eli Lilly, Amgen, Merck, Bristol Myers Squibb, Gilead, Pfizer, and specialty biotechnology companies.","comparables":[{"name":"Johnson & Johnson","ticker":"JNJ","ownership":"Public","relationship":"Operating and valuation reference for ABBV","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABBV.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=JNJ&owner=exclude"},{"name":"Eli Lilly","ticker":"LLY","ownership":"Public","relationship":"Operating and valuation reference for ABBV","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABBV.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=LLY&owner=exclude"},{"name":"Amgen","ticker":"AMGN","ownership":"Public","relationship":"Operating and valuation reference for ABBV","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABBV.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=AMGN&owner=exclude"},{"name":"Merck","ticker":"MRK","ownership":"Public","relationship":"Operating and valuation reference for ABBV","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABBV.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=MRK&owner=exclude"},{"name":"Bristol Myers Squibb","ticker":"BMY","ownership":"Public","relationship":"Operating and valuation reference for ABBV","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABBV.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=BMY&owner=exclude"},{"name":"Gilead Sciences","ticker":"GILD","ownership":"Public","relationship":"Operating and valuation reference for ABBV","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABBV.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=GILD&owner=exclude"}],"sources":[{"title":"ABBV SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=1551152&owner=exclude","excerpt":"The SEC filing record provides ABBV''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"ABBV annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=1551152&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"ABBV quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=1551152&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"ABBV proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=1551152&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"ABBV investor relations","meta":"Company primary materials","href":"https://investors.abbvie.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"ABBV official newsroom","meta":"Company announcements","href":"https://news.abbvie.com/","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}],"evidenceReview":{"reviewedAt":"August 1, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551152&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551152&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551152&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551152&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investors.abbvie.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
