INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('AMGN','published','{"ticker":"AMGN","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.amgen.com/newsroom","description":"Biotechnology company developing and selling medicines across oncology, inflammation, cardiovascular, rare disease, and general medicine.","lede":"AMGEN Inc. earns owner value through prescription product sales through wholesalers, specialty pharmacies, providers, and governments, net of rebates and discounts. The three questions that matter most are key brands, biosimilars, indications, rebates, and competition, obesity, oncology, inflammation, pivotal data, approvals, and probability-adjusted value, rare-disease growth, synergies, debt reduction, interest, and cash conversion.","sells":"Biologic and small-molecule medicines, biosimilars, and therapies from the acquired Horizon portfolio.","revenueModel":"Prescription product sales through wholesalers, specialty pharmacies, providers, and governments, net of rebates and discounts.","opportunity":"Rare-disease growth, obesity assets, biosimilars, and new indications can offset mature-product erosion.","mustGoRight":"Horizon integration must deliver, late-stage trials must validate pipeline value, pricing access must hold, and leverage must decline.","editorNote":"Treat the claimed advantage—biologics expertise, manufacturing, commercial scale, and a diversified portfolio can fund pipeline development and lifecycle management.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Biologics expertise, manufacturing, commercial scale, and a diversified portfolio can fund pipeline development and lifecycle management.","Rare-disease growth, obesity assets, biosimilars, and new indications can offset mature-product erosion.","Visible progress in product volume & price and pipeline can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Patent and biosimilar competition can weaken the owner outcome; monitor loss-of-exclusivity dates, share, net price, and litigation.","Clinical and safety can weaken the owner outcome; monitor trial endpoints, adverse events, regulatory decisions, and labels.","Acquisition and debt can weaken the owner outcome; monitor integration, retention, synergy, leverage, and refinancing.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if acquired growth and pipeline assets fail to offset mature-product competition while debt restricts reinvestment.","financialDrivers":[{"label":"PRODUCT VOLUME & PRICE","value":"Primary owner KPI","detail":"key brands, biosimilars, indications, rebates, and competition"},{"label":"PIPELINE","value":"Primary owner KPI","detail":"obesity, oncology, inflammation, pivotal data, approvals, and probability-adjusted value"},{"label":"HORIZON & LEVERAGE","value":"Primary owner KPI","detail":"rare-disease growth, synergies, debt reduction, interest, and cash conversion"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Patent and biosimilar competition","level":"High","text":"Patent and biosimilar competition can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"loss-of-exclusivity dates, share, net price, and litigation"},{"title":"Clinical and safety","level":"High","text":"Clinical and safety can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"trial endpoints, adverse events, regulatory decisions, and labels"},{"title":"Acquisition and debt","level":"High","text":"Acquisition and debt can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"integration, retention, synergy, leverage, and refinancing"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"PRODUCT VOLUME & PRICE","text":"Track key brands, biosimilars, indications, rebates, and competition and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"PIPELINE","text":"Track obesity, oncology, inflammation, pivotal data, approvals, and probability-adjusted value and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"HORIZON & LEVERAGE","text":"Track rare-disease growth, synergies, debt reduction, interest, and cash conversion and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies product volume & price?","What would cause pipeline to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in horizon & leverage?","Where does AMGEN Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"GILEAD SCIENCES, INC., BIOGEN INC., REGENERON PHARMACEUTICALS, INC., VERTEX PHARMACEUTICALS INC / MA, BRISTOL MYERS SQUIBB CO, AbbVie Inc.","comparables":[{"name":"GILEAD SCIENCES, INC.","ticker":"GILD","ownership":"Public","relationship":"Operating and valuation reference for AMGN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMGN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000882095&owner=exclude"},{"name":"BIOGEN INC.","ticker":"BIIB","ownership":"Public","relationship":"Operating and valuation reference for AMGN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMGN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000875045&owner=exclude"},{"name":"REGENERON PHARMACEUTICALS, INC.","ticker":"REGN","ownership":"Public","relationship":"Operating and valuation reference for AMGN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMGN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000872589&owner=exclude"},{"name":"VERTEX PHARMACEUTICALS INC / MA","ticker":"VRTX","ownership":"Public","relationship":"Operating and valuation reference for AMGN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMGN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000875320&owner=exclude"},{"name":"BRISTOL MYERS SQUIBB CO","ticker":"BMY","ownership":"Public","relationship":"Operating and valuation reference for AMGN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMGN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000014272&owner=exclude"},{"name":"AbbVie Inc.","ticker":"ABBV","ownership":"Public","relationship":"Operating and valuation reference for AMGN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMGN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001551152&owner=exclude"}],"sources":[{"title":"AMGN SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000318154&owner=exclude","excerpt":"AMGEN INC filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"AMGN annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000318154&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"AMGN quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000318154&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"AMGN proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000318154&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"AMGN investor relations","meta":"Company primary materials","href":"https://investors.amgen.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"AMGN official newsroom","meta":"Company announcements","href":"https://www.amgen.com/newsroom","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000318154&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000318154&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000318154&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000318154&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investors.amgen.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
