INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('AMZN','published','{"ticker":"AMZN","description":"Global commerce, cloud infrastructure, advertising, and digital services.","lede":"Amazon combines a high-scale consumer marketplace with AWS, advertising, logistics, and subscription businesses that reinforce one another.","sells":"Online and physical retail, third-party marketplace services, cloud computing, advertising, devices, entertainment, and subscriptions.","revenueModel":"Product sales, seller fees, cloud usage, advertising placements, Prime memberships, and other recurring services.","opportunity":"Commerce scale creates traffic and fulfillment density, while AWS and advertising add higher-margin profit pools.","mustGoRight":"AWS must remain a preferred computing platform, retail efficiency must improve, and capital spending must earn attractive returns.","editorNote":"The ownership debate centers on whether Amazon can convert its unmatched operating footprint into sustainably higher free cash flow without weakening customer value.","bullTitle":"Several durable platforms under one roof","bull":["AWS participates in long-duration cloud and AI infrastructure demand.","Marketplace scale strengthens selection, convenience, and advertising reach.","Fulfillment density and automation can improve retail economics over time."],"bearTitle":"Scale carries a very large reinvestment bill","bear":["Cloud competition can pressure growth and pricing.","Retail remains operationally complex and exposed to labor and delivery costs.","Heavy infrastructure spending can outrun monetization."],"thesisBreaker":"A sustained loss of AWS relevance combined with structurally weak retail returns would undermine the case that Amazon’s reinvestment compounds owner value.","financialDrivers":[{"label":"Q1 REVENUE","value":"$181.5B · +17%","detail":"North America, International, and AWS must be separated because their economics and capital needs differ"},{"label":"AWS","value":"$37.6B · +28%","detail":"Cloud usage, capacity, custom silicon, AI services, and operating margin"},{"label":"OPERATING INCOME","value":"$23.9B","detail":"Retail productivity and AWS mix drove improvement; owner focus remains conversion to durable free cash flow"},{"label":"AI INFRASTRUCTURE","value":">$20B chip run-rate","detail":"Company-stated annual run rate for Graviton, Trainium, and Nitro; track utilization and returns on data-center investment"},{"label":"FREE CASH FLOW","value":"Owner cash test","detail":"Operating cash flow less equipment, data-center, fulfillment, and finance-lease investment"},{"label":"CAPITAL EMPLOYED","value":"Return discipline","detail":"AWS infrastructure, logistics, leases, content, acquisitions, and working capital"}],"risks":[{"title":"Capital intensity","level":"High","text":"Data centers and fulfillment infrastructure require substantial capital before demand is fully visible.","signal":"Capex growth versus operating cash flow"},{"title":"Cloud competition","level":"High","text":"Microsoft, Google, and specialized providers compete for enterprise and AI workloads.","signal":"AWS growth and margin trend"},{"title":"Regulatory scrutiny","level":"Medium","text":"Marketplace practices, labor, data, and competition remain under global review.","signal":"Material remedies or operating restrictions"},{"title":"Operating complexity and labor","level":"High","text":"Fulfillment, delivery, workplace, wage, contractor, and safety execution can create cost and regulatory pressure.","signal":"Cost to serve, injury metrics, wages, delivery speed, labor actions, and regulatory findings"},{"title":"Content, devices, and experimental allocation","level":"Medium","text":"Media, healthcare, devices, satellites, and other initiatives can consume capital without strengthening core returns.","signal":"Segment disclosures, impairments, restructuring, cash commitments, and adoption milestones"}],"monitor":[{"title":"AWS growth versus infrastructure returns","text":"Compare cloud growth and operating income with capital expenditures, useful capacity, customer commitments, and asset lives.","impact":"BULL CASE"},{"title":"Retail cost-to-serve","text":"Track delivery speed, inventory placement, regionalization, labor, transportation, and third-party seller economics.","impact":"NEUTRAL"},{"title":"Custom silicon adoption","text":"Measure Trainium and Graviton workload penetration without assuming every deployed chip displaces an external accelerator dollar-for-dollar.","impact":"NEUTRAL"},{"title":"Free cash flow after leases","text":"Reconcile operating cash flow with equipment purchases, finance leases, stock compensation, and working-capital timing.","impact":"NEUTRAL"}],"questions":["What cash return will the current AI infrastructure cycle earn?","How much retail margin improvement is structural rather than mix or timing?","Can advertising expand without degrading marketplace trust?","Where does Amazon Leo become a material standalone profit pool?","What normalized free cash flow remains after all AWS and logistics lease commitments?","Which non-core initiatives have explicit return hurdles and exit criteria?"],"competitors":"Microsoft Azure, Google Cloud, Walmart, Shopify, Alibaba, and digital advertising platforms.","sources":[{"title":"Amazon SEC filing library","meta":"SEC EDGAR · Primary filings","href":"https://www.sec.gov/edgar/browse/?CIK=1018724&owner=exclude","excerpt":"Amazon filings report North America, International, and AWS results and disclose customers, competition, infrastructure, fulfillment, leases, commitments, regulation, and risk."},{"title":"Amazon First-Quarter 2026 Results","meta":"Company earnings release · April 29, 2026","href":"https://ir.aboutamazon.com/news-release/news-release-details/2026/Amazon-com-Announces-First-Quarter-Results/","excerpt":"The official release reports segment sales and operating income, cash flow, guidance, and management''s operating highlights."},{"title":"Amazon Quarterly Results","meta":"Company financial archive","href":"https://ir.aboutamazon.com/quarterly-results/default.aspx","excerpt":"Official earnings releases, slides, webcasts, and quarterly filing links across reporting periods."},{"title":"Amazon Investor Relations","meta":"Company primary materials","href":"https://ir.aboutamazon.com/","excerpt":"Annual reports, proxies, shareholder letters, SEC filings, press releases, governance information, and events."},{"title":"Amazon Annual Reports and Proxies","meta":"Company annual filing archive","href":"https://ir.aboutamazon.com/annual-reports-proxies-and-shareholder-letters/default.aspx","excerpt":"Annual reports, proxies, and shareholder letters provide long-term evidence on segments, capital allocation, governance, commitments, and risk."}],"reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://ir.aboutamazon.com/news-release/news-release-details/default.aspx","comparables":[{"name":"Microsoft","ticker":"MSFT","ownership":"Public","relationship":"Primary enterprise cloud and AI platform competitor","valuation":"Compare cloud growth, margin, and capital intensity","financialStatus":"Highly profitable software and cloud platform with a larger recurring software mix.","sourceUrl":"https://www.microsoft.com/en-us/Investor"},{"name":"Alphabet","ticker":"GOOGL","ownership":"Public","relationship":"Cloud, advertising, AI, devices, and commerce-adjacent competitor","valuation":"Compare cloud profitability and advertising economics","financialStatus":"Advertising-funded platform with a profitable cloud segment and large AI investment program.","sourceUrl":"https://abc.xyz/investor/"},{"name":"Walmart","ticker":"WMT","ownership":"Public","relationship":"Scaled retail, marketplace, advertising, and fulfillment competitor","valuation":"Retail multiples require margin and working-capital context","financialStatus":"Profitable global retailer with stores that also serve as fulfillment infrastructure.","sourceUrl":"https://stock.walmart.com/"},{"name":"Shopify","ticker":"SHOP","ownership":"Public","relationship":"Merchant software, payments, and commerce ecosystem competitor","valuation":"Compare gross profit and free-cash-flow growth rather than GMV alone","financialStatus":"Asset-lighter merchant platform with transaction and subscription economics.","sourceUrl":"https://investors.shopify.com/"},{"name":"Oracle","ticker":"ORCL","ownership":"Public","relationship":"Cloud infrastructure and database competitor","valuation":"Adjust for debt, leases, and data-center commitments","financialStatus":"Profitable software franchise undertaking a capital-intensive cloud buildout.","sourceUrl":"https://investor.oracle.com/"},{"name":"MercadoLibre","ticker":"MELI","ownership":"Public","relationship":"Marketplace, logistics, advertising, and payments comparable","valuation":"Compare geography, fintech credit, margin, and growth","financialStatus":"Profitable Latin American commerce and fintech platform with different macro exposure.","sourceUrl":"https://investor.mercadolibre.com/"}],"evidenceReview":{"reviewedAt":"August 1, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001018724&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001018724&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001018724&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001018724&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://ir.aboutamazon.com/news-release/news-release-details/2026/Amazon-com-Announces-First-Quarter-Results/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
