INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('ANET','published','{"ticker":"ANET","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.arista.com/en/company/news","description":"Cloud-networking company supplying high-speed switches, routing, software, and observability for data centers and campuses.","lede":"ARISTA NETWORKS Inc. earns owner value through hardware appliance sales plus software subscriptions, support, maintenance, and services. The three questions that matter most are customer capex, share, 400g/800g migration, program timing, and concentration, ethernet cluster wins, ports, optics, software, and competitive performance, campus adoption, subscriptions, support, recurring mix, and channel productivity.","sells":"Ethernet switches, routers, network software, telemetry, security, support, and campus networking products.","revenueModel":"Hardware appliance sales plus software subscriptions, support, maintenance, and services.","opportunity":"AI clusters, data-center bandwidth, campus expansion, and software attach can increase ports, speeds, and recurring revenue.","mustGoRight":"AI Ethernet must win at scale, customer concentration must not destabilize growth, and supply and product cadence must execute.","editorNote":"Treat the claimed advantage—a common software architecture, merchant silicon expertise, and cloud-scale customer relationships can support rapid networking innovation.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["A common software architecture, merchant silicon expertise, and cloud-scale customer relationships can support rapid networking innovation.","AI clusters, data-center bandwidth, campus expansion, and software attach can increase ports, speeds, and recurring revenue.","Visible progress in cloud titans and ai networking can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Customer concentration can weaken the owner outcome; monitor top-customer share, capex cycles, insourcing, and pricing.","Technology competition can weaken the owner outcome; monitor ethernet versus proprietary fabrics, cisco, white box, and product benchmarks.","Supply and components can weaken the owner outcome; monitor lead times, optics, merchant silicon, inventory, and purchase commitments.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if proprietary fabrics or larger vendors displace Arista in AI and cloud networks while its key customers insource or diversify.","financialDrivers":[{"label":"CLOUD TITANS","value":"Primary owner KPI","detail":"customer capex, share, 400G/800G migration, program timing, and concentration"},{"label":"AI NETWORKING","value":"Primary owner KPI","detail":"Ethernet cluster wins, ports, optics, software, and competitive performance"},{"label":"ENTERPRISE & SOFTWARE","value":"Primary owner KPI","detail":"campus adoption, subscriptions, support, recurring mix, and channel productivity"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Customer concentration","level":"High","text":"Customer concentration can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"top-customer share, capex cycles, insourcing, and pricing"},{"title":"Technology competition","level":"High","text":"Technology competition can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"Ethernet versus proprietary fabrics, Cisco, white box, and product benchmarks"},{"title":"Supply and components","level":"High","text":"Supply and components can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"lead times, optics, merchant silicon, inventory, and purchase commitments"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"CLOUD TITANS","text":"Track customer capex, share, 400g/800g migration, program timing, and concentration and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"AI NETWORKING","text":"Track ethernet cluster wins, ports, optics, software, and competitive performance and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"ENTERPRISE & SOFTWARE","text":"Track campus adoption, subscriptions, support, recurring mix, and channel productivity and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies cloud titans?","What would cause ai networking to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in enterprise & software?","Where does ARISTA NETWORKS Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"CISCO SYSTEMS, INC., JNPR, Hewlett Packard Enterprise Co, Dell Technologies Inc., Broadcom Inc., NVIDIA CORP","comparables":[{"name":"CISCO SYSTEMS, INC.","ticker":"CSCO","ownership":"Public","relationship":"Operating and valuation reference for ANET","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ANET.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000858877&owner=exclude"},{"name":"JNPR","ticker":"JNPR","ownership":"Public","relationship":"Operating and valuation reference for ANET","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ANET.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=JNPR&owner=exclude"},{"name":"Hewlett Packard Enterprise Co","ticker":"HPE","ownership":"Public","relationship":"Operating and valuation reference for ANET","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ANET.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001645590&owner=exclude"},{"name":"Dell Technologies Inc.","ticker":"DELL","ownership":"Public","relationship":"Operating and valuation reference for ANET","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ANET.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001571996&owner=exclude"},{"name":"Broadcom Inc.","ticker":"AVGO","ownership":"Public","relationship":"Operating and valuation reference for ANET","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ANET.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001730168&owner=exclude"},{"name":"NVIDIA CORP","ticker":"NVDA","ownership":"Public","relationship":"Operating and valuation reference for ANET","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ANET.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001045810&owner=exclude"}],"sources":[{"title":"ANET SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0001596532&owner=exclude","excerpt":"Arista Networks, Inc. filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"ANET annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001596532&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"ANET quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001596532&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"ANET proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001596532&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"ANET investor relations","meta":"Company primary materials","href":"https://investors.arista.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"ANET official newsroom","meta":"Company announcements","href":"https://www.arista.com/en/company/news","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001596532&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001596532&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001596532&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001596532&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investors.arista.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
