INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('APH','published','{"ticker":"APH","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.amphenol.com/news","description":"Global interconnect, sensor, antenna, and cable manufacturer serving communications, industrial, automotive, aerospace, defense, and mobile markets.","lede":"AMPHENOL Corp. earns owner value through engineered component and subsystem sales to oems, contract manufacturers, distributors, and government-related customers. The three questions that matter most are content per platform, units, pricing, end-market mix, and share, high-speed interconnect, power, networking, customer programs, and capacity, purchase price, organic follow-through, margin, integration, and return on capital.","sells":"Connectors, high-speed cables, sensors, antennas, fiber systems, power interconnects, and harsh-environment components.","revenueModel":"Engineered component and subsystem sales to OEMs, contract manufacturers, distributors, and government-related customers.","opportunity":"AI data centers, electrification, aerospace, defense, and vehicle electronics can drive content growth and share.","mustGoRight":"Acquisitions must retain returns, program content must convert to volume, and customer and end-market concentration must remain manageable.","editorNote":"Treat the claimed advantage—broad engineering capabilities, decentralized execution, customer design-in, and acquisitions can expand content across platforms.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Broad engineering capabilities, decentralized execution, customer design-in, and acquisitions can expand content across platforms.","AI data centers, electrification, aerospace, defense, and vehicle electronics can drive content growth and share.","Visible progress in organic growth and ai & communications can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Electronics cycle and concentration can weaken the owner outcome; monitor customer programs, inventory, units, mix, and cancellations.","Acquisition execution can weaken the owner outcome; monitor goodwill, integration, retention, synergies, and organic growth.","Supply and trade can weaken the owner outcome; monitor metals, components, tariffs, export controls, and regional manufacturing.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if acquisition-led growth masks organic share loss and rising capital deployment fails to sustain margins and returns.","financialDrivers":[{"label":"ORGANIC GROWTH","value":"Primary owner KPI","detail":"content per platform, units, pricing, end-market mix, and share"},{"label":"AI & COMMUNICATIONS","value":"Primary owner KPI","detail":"high-speed interconnect, power, networking, customer programs, and capacity"},{"label":"ACQUISITIONS","value":"Primary owner KPI","detail":"purchase price, organic follow-through, margin, integration, and return on capital"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Electronics cycle and concentration","level":"High","text":"Electronics cycle and concentration can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"customer programs, inventory, units, mix, and cancellations"},{"title":"Acquisition execution","level":"High","text":"Acquisition execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"goodwill, integration, retention, synergies, and organic growth"},{"title":"Supply and trade","level":"High","text":"Supply and trade can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"metals, components, tariffs, export controls, and regional manufacturing"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"ORGANIC GROWTH","text":"Track content per platform, units, pricing, end-market mix, and share and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"AI & COMMUNICATIONS","text":"Track high-speed interconnect, power, networking, customer programs, and capacity and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"ACQUISITIONS","text":"Track purchase price, organic follow-through, margin, integration, and return on capital and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies organic growth?","What would cause ai & communications to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in acquisitions?","Where does AMPHENOL Corp. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"TE Connectivity plc, CORNING INC /NY, Keysight Technologies, Inc., JABIL INC, FLEX LTD., TTM TECHNOLOGIES INC","comparables":[{"name":"TE Connectivity plc","ticker":"TEL","ownership":"Public","relationship":"Operating and valuation reference for APH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with APH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001385157&owner=exclude"},{"name":"CORNING INC /NY","ticker":"GLW","ownership":"Public","relationship":"Operating and valuation reference for APH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with APH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000024741&owner=exclude"},{"name":"Keysight Technologies, Inc.","ticker":"KEYS","ownership":"Public","relationship":"Operating and valuation reference for APH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with APH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001601046&owner=exclude"},{"name":"JABIL INC","ticker":"JBL","ownership":"Public","relationship":"Operating and valuation reference for APH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with APH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000898293&owner=exclude"},{"name":"FLEX LTD.","ticker":"FLEX","ownership":"Public","relationship":"Operating and valuation reference for APH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with APH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000866374&owner=exclude"},{"name":"TTM TECHNOLOGIES INC","ticker":"TTMI","ownership":"Public","relationship":"Operating and valuation reference for APH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with APH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001116942&owner=exclude"}],"sources":[{"title":"APH SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000820313&owner=exclude","excerpt":"AMPHENOL CORP filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"APH annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000820313&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"APH quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000820313&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"APH proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000820313&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"APH investor relations","meta":"Company primary materials","href":"https://investors.amphenol.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"APH official newsroom","meta":"Company announcements","href":"https://www.amphenol.com/news","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000820313&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000820313&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000820313&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000820313&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investors.amphenol.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
