INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('AXP','published','{"ticker":"AXP","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://ir.americanexpress.com/news/investor-relations-news/default.aspx","description":"Integrated payments, card-issuing, merchant-acquiring, travel, and lending company serving consumers and businesses.","lede":"AMERICAN EXPRESS earns owner value through discount revenue, card fees, net interest income, travel commissions, and other payment and service fees. The three questions that matter most are cardmember spend, travel, goods and services, fx, and merchant coverage, fees, rewards, retention, acquisition cost, and cohort lifetime value, loan growth, delinquencies, charge-offs, reserves, deposits, and funding cost.","sells":"Charge and credit cards, merchant acceptance, rewards, travel, working-capital products, and business payments.","revenueModel":"Discount revenue, card fees, net interest income, travel commissions, and other payment and service fees.","opportunity":"New card members, younger cohorts, international acceptance, business payments, and fee growth can expand the franchise.","mustGoRight":"Spend and retention must support rewards and marketing, credit must normalize within expectations, and merchant acceptance must remain broad.","editorNote":"Treat the claimed advantage—a closed-loop network, affluent customer base, rewards, and merchant data can reinforce spend and premium economics.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["A closed-loop network, affluent customer base, rewards, and merchant data can reinforce spend and premium economics.","New card members, younger cohorts, international acceptance, business payments, and fee growth can expand the franchise.","Visible progress in billed business and cardmember economics can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Consumer and travel cycle can weaken the owner outcome; monitor spend, unemployment, travel volume, and corporate budgets.","Rewards competition can weaken the owner outcome; monitor acquisition offers, reward cost, retention, and co-brand terms.","Credit and funding can weaken the owner outcome; monitor delinquencies, vintages, reserve coverage, deposit beta, and liquidity.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if premium customer growth requires uneconomic rewards and marketing while credit losses and funding costs rise.","financialDrivers":[{"label":"BILLED BUSINESS","value":"Primary owner KPI","detail":"cardmember spend, travel, goods and services, FX, and merchant coverage"},{"label":"CARDMEMBER ECONOMICS","value":"Primary owner KPI","detail":"fees, rewards, retention, acquisition cost, and cohort lifetime value"},{"label":"CREDIT & FUNDING","value":"Primary owner KPI","detail":"loan growth, delinquencies, charge-offs, reserves, deposits, and funding cost"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Consumer and travel cycle","level":"High","text":"Consumer and travel cycle can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"spend, unemployment, travel volume, and corporate budgets"},{"title":"Rewards competition","level":"High","text":"Rewards competition can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"acquisition offers, reward cost, retention, and co-brand terms"},{"title":"Credit and funding","level":"High","text":"Credit and funding can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"delinquencies, vintages, reserve coverage, deposit beta, and liquidity"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"BILLED BUSINESS","text":"Track cardmember spend, travel, goods and services, fx, and merchant coverage and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"CARDMEMBER ECONOMICS","text":"Track fees, rewards, retention, acquisition cost, and cohort lifetime value and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"CREDIT & FUNDING","text":"Track loan growth, delinquencies, charge-offs, reserves, deposits, and funding cost and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies billed business?","What would cause cardmember economics to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in credit & funding?","Where does AMERICAN EXPRESS have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"VISA INC., Mastercard Inc, CAPITAL ONE FINANCIAL CORP, DFS, JPMORGAN CHASE & CO, CITIGROUP INC","comparables":[{"name":"VISA INC.","ticker":"V","ownership":"Public","relationship":"Operating and valuation reference for AXP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AXP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001403161&owner=exclude"},{"name":"Mastercard Inc","ticker":"MA","ownership":"Public","relationship":"Operating and valuation reference for AXP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AXP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001141391&owner=exclude"},{"name":"CAPITAL ONE FINANCIAL CORP","ticker":"COF","ownership":"Public","relationship":"Operating and valuation reference for AXP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AXP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000927628&owner=exclude"},{"name":"DFS","ticker":"DFS","ownership":"Public","relationship":"Operating and valuation reference for AXP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AXP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=DFS&owner=exclude"},{"name":"JPMORGAN CHASE & CO","ticker":"JPM","ownership":"Public","relationship":"Operating and valuation reference for AXP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AXP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000019617&owner=exclude"},{"name":"CITIGROUP INC","ticker":"C","ownership":"Public","relationship":"Operating and valuation reference for AXP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AXP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000831001&owner=exclude"}],"sources":[{"title":"AXP SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000004962&owner=exclude","excerpt":"AMERICAN EXPRESS CO filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"AXP annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000004962&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"AXP quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000004962&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"AXP proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000004962&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"AXP investor relations","meta":"Company primary materials","href":"https://ir.americanexpress.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"AXP official newsroom","meta":"Company announcements","href":"https://ir.americanexpress.com/news/investor-relations-news/default.aspx","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000004962&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000004962&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000004962&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000004962&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://ir.americanexpress.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
