INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('BA','published','{"ticker":"BA","description":"Commercial aircraft, defense systems, space programs, and global aviation services.","lede":"Boeing is one of the world’s two major large-commercial-aircraft manufacturers and also operates significant defense, space, and services businesses.","sells":"Commercial airplanes, military aircraft, satellites, weapons, space systems, spare parts, maintenance, training, and analytics.","revenueModel":"Aircraft and system deliveries, long-term development and production contracts, aftermarket parts, maintenance, and services.","opportunity":"A large installed base, substantial backlog, air-traffic growth, and strategic defense programs create long-duration demand.","mustGoRight":"Boeing must restore safety and production stability, improve supplier performance, execute fixed-price programs, and rebuild cash generation.","editorNote":"For Boeing, production quality and organizational discipline are the thesis. Backlog matters only if aircraft can be delivered safely, predictably, and profitably.","bullTitle":"Scarce strategic assets with long-duration demand","bull":["The commercial-aircraft market has very high barriers to entry.","Backlog and fleet replacement support long-term delivery demand.","Services and defense provide additional installed-base and strategic value."],"bearTitle":"Execution failures can overwhelm franchise value","bear":["Quality and safety problems can slow production and damage trust.","Fixed-price defense programs can generate large charges.","A leveraged balance sheet reduces room for prolonged disruption."],"thesisBreaker":"Failure to establish a durable safety and production system—rather than a temporary recovery—would impair customer trust, cash generation, and strategic value.","financialDrivers":[{"label":"Q1 REVENUE","value":"$22.2B · +14%","detail":"Commercial deliveries and defense/services mix; volume is only useful when quality and program economics improve"},{"label":"Q2 DELIVERIES","value":"171 aircraft","detail":"129 737s and 25 787s among Q2 deliveries; cash timing and customer acceptance remain critical"},{"label":"TOTAL BACKLOG","value":"$694.7B","detail":"March 2026 company backlog, including $575.6B of Commercial Airplanes; backlog is not profit"},{"label":"FREE CASH FLOW","value":"Recovery test","detail":"Advances, inventory, delivery payments, supplier support, certification, and program charges drive cash conversion"},{"label":"COMMERCIAL DELIVERIES","value":"Cash conversion","detail":"737, 787, and widebody production, certification, rework, pricing, advances, and customer acceptance"},{"label":"FREE CASH FLOW","value":"Recovery test","detail":"Customer advances, inventory, supplier payments, production stabilization, defense charges, and capex"}],"risks":[{"title":"Safety and quality","level":"High","text":"Manufacturing control and product safety directly affect approvals, deliveries, and trust.","signal":"Regulatory findings and production holds"},{"title":"Balance sheet","level":"High","text":"Debt and cash needs constrain recovery flexibility.","signal":"Free cash flow and net debt"},{"title":"Defense program charges","level":"High","text":"Fixed-price development programs can require further cost recognition.","signal":"Quarterly reach-forward losses"},{"title":"Quality, certification, and production","level":"High","text":"Manufacturing defects, supplier nonconformance, regulatory findings, or accidents can stop deliveries and increase rework and compensation.","signal":"FAA actions, traveled work, inventory, deliveries, rework, customer claims, and incident findings"},{"title":"Fixed-price defense programs","level":"High","text":"Development and production contracts can generate additional reach-forward losses when schedules, design, or labor assumptions change.","signal":"Program charges, estimate-at-completion revisions, milestones, and contract modifications"}],"monitor":[{"title":"737 and 787 stable production","text":"Track conforming units, traveled work, rework, supplier readiness, FAA oversight, deliveries, and inventory—not monthly rate alone.","impact":"BULL CASE"},{"title":"Certification and development programs","text":"Follow 737-7/-10, 777X, defense development milestones, schedule, and cumulative charges.","impact":"NEUTRAL"},{"title":"Cash and balance sheet","text":"Reconcile delivery growth to advances, inventory, free cash flow, debt, pensions, customer concessions, and supplier financing.","impact":"BEAR CASE"},{"title":"Delivery-to-cash conversion","text":"Compare production and deliveries with inventory, advances, supplier payments, concessions, and free cash flow.","impact":"NEUTRAL"}],"questions":["What evidence proves production stability rather than short-term delivery catch-up?","Which fixed-price defense programs still carry material loss risk?","When will inventory and advances convert into durable free cash flow?","How much capital and management attention will integration and certification require?","What objective quality metrics determine whether production can safely increase?","Which fixed-price programs still contain the largest unrecognized downside scenarios?"],"competitors":"Airbus, Lockheed Martin, Northrop Grumman, RTX, General Dynamics, Embraer, and emerging aircraft manufacturers.","sources":[{"title":"Boeing SEC filing library","meta":"SEC EDGAR · Primary filings","href":"https://www.sec.gov/edgar/browse/?CIK=12927&owner=exclude","excerpt":"Boeing filings describe commercial, defense, space, and services programs; inventories; advances; debt; certification; suppliers; contingencies; and program accounting."},{"title":"Boeing First-Quarter 2026 Results","meta":"Company earnings release · April 22, 2026","href":"https://investors.boeing.com/investors/news/press-release-details/2026/Boeing-Reports-First-Quarter-Results/default.aspx","excerpt":"The official release reports revenue, delivery, margin, cash flow, backlog, production, certification, and segment results."},{"title":"Boeing Q2 2026 Deliveries","meta":"Company operational release · July 14, 2026","href":"https://investors.boeing.com/investors/news/press-release-details/2026/Boeing-Announces-Second-Quarter-Deliveries/default.aspx","excerpt":"The release reports commercial and defense program deliveries for the quarter and year to date while noting that delivery data is not final financial performance."},{"title":"Boeing Investor Reports","meta":"Company primary materials","href":"https://investors.boeing.com/investors/reports/default.aspx","excerpt":"Quarterly and annual reports, SEC filings, sustainability materials, accounting considerations, and interactive financial information."},{"title":"Boeing Proxy Statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000012927&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose beneficial ownership, board oversight, executive incentives, related matters, and shareholder proposals."}],"reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://investors.boeing.com/investors/news/","comparables":[{"name":"Airbus","ticker":"AIR.PA","ownership":"Public","relationship":"Primary large-commercial-aircraft competitor","valuation":"Compare delivery mix, backlog, advances, net cash, and program risk","financialStatus":"Profitable global aerospace group with commercial, helicopter, and defense operations.","sourceUrl":"https://www.airbus.com/en/investors"},{"name":"Lockheed Martin","ticker":"LMT","ownership":"Public","relationship":"Defense, space, and government-program competitor","valuation":"Compare backlog quality, margins, and cash conversion","financialStatus":"Large profitable defense prime with lower commercial-aerospace exposure.","sourceUrl":"https://investors.lockheedmartin.com/"},{"name":"RTX","ticker":"RTX","ownership":"Public","relationship":"Commercial engines, systems, aftermarket, and defense comparable","valuation":"Separate Pratt, Collins, and Raytheon economics","financialStatus":"Diversified aerospace and defense supplier with large aftermarket exposure.","sourceUrl":"https://investors.rtx.com/"},{"name":"Northrop Grumman","ticker":"NOC","ownership":"Public","relationship":"Defense, space, and fixed-price program comparable","valuation":"Compare funded backlog, margin, and program-charge risk","financialStatus":"Large profitable defense prime concentrated in government programs.","sourceUrl":"https://investor.northropgrumman.com/"},{"name":"Embraer","ticker":"ERJ","ownership":"Public","relationship":"Commercial aircraft and services competitor","valuation":"Compare backlog, delivery growth, margin, and net debt","financialStatus":"Smaller profitable aircraft manufacturer focused on regional and executive markets.","sourceUrl":"https://ri.embraer.com.br/en/"},{"name":"General Dynamics","ticker":"GD","ownership":"Public","relationship":"Defense and business-jet manufacturing comparable","valuation":"Separate Gulfstream and defense segments","financialStatus":"Profitable diversified contractor with a different fixed-price and commercial mix.","sourceUrl":"https://investorrelations.gd.com/"}],"evidenceReview":{"reviewedAt":"August 1, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000012927&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000012927&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000012927&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000012927&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investors.boeing.com/investors/news/press-release-details/2026/Boeing-Reports-First-Quarter-Results/default.aspx","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
