INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('BAC','published','{"ticker":"BAC","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://newsroom.bankofamerica.com/","description":"Diversified financial institution serving consumers, small businesses, corporations, institutions, and wealth clients.","lede":"Bank of America''s value rests on a large deposit franchise, disciplined credit, and fee businesses. Owners must normalize rate sensitivity and verify that technology and distribution produce durable operating leverage.","sells":"Deposits, cards, mortgages, consumer and commercial loans, cash management, investment banking, markets, brokerage, and wealth management.","revenueModel":"Net interest income plus card, service, investment-banking, markets, brokerage, and asset-management fees, net of credit and operating costs.","opportunity":"Low-cost deposits, digital engagement, Merrill and private-bank relationships, and commercial scale can deepen customer economics.","mustGoRight":"Deposit pricing must remain rational, securities and rate exposure must be managed, credit must hold, fees must grow, and capital requirements must support acceptable returns.","editorNote":"Reconcile accounting net interest income with deposit behavior and accumulated securities economics; then assess returns on tangible equity through a full rate and credit cycle.","bullTitle":"What can compound owner value","bull":["A broad consumer deposit base supports funding and relationships.","Merrill and private banking add fee and wealth diversification.","Digital adoption can reduce unit cost and deepen engagement.","Capital-markets and commercial franchises broaden revenue."],"bearTitle":"What can impair the thesis","bear":["Deposit repricing and rate changes can pressure spread income.","Consumer and commercial credit losses can rise together.","Securities duration and capital rules constrain flexibility.","Operational, cyber, and conduct failures can create large costs."],"thesisBreaker":"The thesis breaks if the deposit franchise proves structurally less valuable and credit, securities, or control losses prevent the bank from earning its cost of equity through the cycle.","financialDrivers":[{"label":"NET INTEREST INCOME","value":"Deposit and rate economics","detail":"Balances, beta, asset yields, securities, funding, and hedges"},{"label":"CREDIT","value":"Loss cycle","detail":"Delinquencies, charge-offs, reserves, card, commercial real estate, and cohorts"},{"label":"FEES","value":"Wealth and markets","detail":"Client assets, flows, brokerage, investment banking, markets, and service fees"},{"label":"CAPITAL","value":"Constraint and distribution","detail":"CET1, stress losses, risk-weighted assets, dividends, and repurchases"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Rate and deposit sensitivity","level":"High","text":"Funding costs can rise faster than asset yields.","signal":"Deposit mix, beta, balances, NII guidance, and securities yields"},{"title":"Credit deterioration","level":"High","text":"Consumer or commercial losses can exceed reserves.","signal":"Delinquencies, criticized loans, charge-offs, and reserve coverage"},{"title":"Capital and controls","level":"High","text":"Rules or operational failures can increase required capital and expense.","signal":"Stress tests, CET1, enforcement, remediation, and outages"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Deposit franchise","text":"Track balances, mix, pricing, and primary-account retention.","impact":"NEUTRAL"},{"title":"Card and commercial credit","text":"Follow cohorts and early delinquencies before losses peak.","impact":"BEAR CASE"},{"title":"Wealth flows","text":"Measure organic client assets and fee conversion.","impact":"BULL CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["What is normalized NII across plausible rate paths?","Which credit book has the greatest downside convexity?","How much capital could revised rules require?","Is digital investment lowering cost per relationship?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"JPMorgan Chase, Wells Fargo, Citigroup, U.S. Bancorp, Goldman Sachs, Morgan Stanley, regional banks, and fintechs.","comparables":[{"name":"JPMorgan Chase","ticker":"JPM","ownership":"Public","relationship":"Operating and valuation reference for BAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=JPM&owner=exclude"},{"name":"Wells Fargo","ticker":"WFC","ownership":"Public","relationship":"Operating and valuation reference for BAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=WFC&owner=exclude"},{"name":"Citigroup","ticker":"C","ownership":"Public","relationship":"Operating and valuation reference for BAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=C&owner=exclude"},{"name":"U.S. Bancorp","ticker":"USB","ownership":"Public","relationship":"Operating and valuation reference for BAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=USB&owner=exclude"},{"name":"Goldman Sachs","ticker":"GS","ownership":"Public","relationship":"Operating and valuation reference for BAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=GS&owner=exclude"},{"name":"Morgan Stanley","ticker":"MS","ownership":"Public","relationship":"Operating and valuation reference for BAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=MS&owner=exclude"}],"sources":[{"title":"BAC SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=70858&owner=exclude","excerpt":"The SEC filing record provides BAC''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"BAC annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=70858&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"BAC quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=70858&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"BAC proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=70858&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"BAC investor relations","meta":"Company primary materials","href":"https://investor.bankofamerica.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"BAC official newsroom","meta":"Company announcements","href":"https://newsroom.bankofamerica.com/","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}],"evidenceReview":{"reviewedAt":"August 1, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000070858&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000070858&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000070858&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000070858&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investor.bankofamerica.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
