INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('BKNG','published','{"ticker":"BKNG","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.bookingholdings.com/news/","description":"Global online travel platform operating Booking.com, Priceline, Agoda, KAYAK, OpenTable, and related services.","lede":"BOOKING HOLDINGS Inc. earns owner value through travel reservation commissions, merchant margins, payment economics, advertising, and restaurant fees. The three questions that matter most are bookings, adr, cancellations, geography, alternative accommodations, and travel demand, merchant mix, commissions, paid traffic, direct share, and customer acquisition cost, merchant bookings, flights, attractions, fraud, working capital, and cross-sell.","sells":"Accommodation, flight, car-rental, attraction, restaurant, advertising, and payment services.","revenueModel":"Travel reservation commissions, merchant margins, payment economics, advertising, and restaurant fees.","opportunity":"Alternative accommodations, flights, connected trips, payments, Asia, and direct booking can deepen wallet share.","mustGoRight":"Room-night growth must remain profitable, performance marketing must stay efficient, and regulatory and payment costs must be contained.","editorNote":"Treat the claimed advantage—global accommodation supply, direct traffic, brand, reviews, and payments can reinforce marketplace liquidity.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Global accommodation supply, direct traffic, brand, reviews, and payments can reinforce marketplace liquidity.","Alternative accommodations, flights, connected trips, payments, Asia, and direct booking can deepen wallet share.","Visible progress in room nights and take rate & marketing can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Travel cycle and geopolitics can weaken the owner outcome; monitor bookings, cancellations, adr, borders, currency, and regional events.","Platform and search dependence can weaken the owner outcome; monitor google traffic, app direct share, marketing roi, and supplier direct booking.","Regulation and tax can weaken the owner outcome; monitor digital-market rules, parity, consumer law, tax assessments, and remedies.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if direct traffic weakens and rising marketing, regulation, and supplier power structurally compress take rate and cash returns.","financialDrivers":[{"label":"ROOM NIGHTS","value":"Primary owner KPI","detail":"bookings, ADR, cancellations, geography, alternative accommodations, and travel demand"},{"label":"TAKE RATE & MARKETING","value":"Primary owner KPI","detail":"merchant mix, commissions, paid traffic, direct share, and customer acquisition cost"},{"label":"PAYMENTS & CONNECTED TRIP","value":"Primary owner KPI","detail":"merchant bookings, flights, attractions, fraud, working capital, and cross-sell"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Travel cycle and geopolitics","level":"High","text":"Travel cycle and geopolitics can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"bookings, cancellations, ADR, borders, currency, and regional events"},{"title":"Platform and search dependence","level":"High","text":"Platform and search dependence can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"Google traffic, app direct share, marketing ROI, and supplier direct booking"},{"title":"Regulation and tax","level":"High","text":"Regulation and tax can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"digital-market rules, parity, consumer law, tax assessments, and remedies"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"ROOM NIGHTS","text":"Track bookings, adr, cancellations, geography, alternative accommodations, and travel demand and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"TAKE RATE & MARKETING","text":"Track merchant mix, commissions, paid traffic, direct share, and customer acquisition cost and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"PAYMENTS & CONNECTED TRIP","text":"Track merchant bookings, flights, attractions, fraud, working capital, and cross-sell and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies room nights?","What would cause take rate & marketing to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in payments & connected trip?","Where does BOOKING HOLDINGS Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"Expedia Group, Inc., Airbnb, Inc., TripAdvisor, Inc., TCOM, Uber Technologies, Inc, MARRIOTT INTERNATIONAL INC","comparables":[{"name":"Expedia Group, Inc.","ticker":"EXPE","ownership":"Public","relationship":"Operating and valuation reference for BKNG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BKNG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001324424&owner=exclude"},{"name":"Airbnb, Inc.","ticker":"ABNB","ownership":"Public","relationship":"Operating and valuation reference for BKNG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BKNG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001559720&owner=exclude"},{"name":"TripAdvisor, Inc.","ticker":"TRIP","ownership":"Public","relationship":"Operating and valuation reference for BKNG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BKNG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001526520&owner=exclude"},{"name":"TCOM","ticker":"TCOM","ownership":"Public","relationship":"Operating and valuation reference for BKNG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BKNG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=TCOM&owner=exclude"},{"name":"Uber Technologies, Inc","ticker":"UBER","ownership":"Public","relationship":"Operating and valuation reference for BKNG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BKNG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001543151&owner=exclude"},{"name":"MARRIOTT INTERNATIONAL INC","ticker":"MAR","ownership":"Public","relationship":"Operating and valuation reference for BKNG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BKNG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001048286&owner=exclude"}],"sources":[{"title":"BKNG SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0001075531&owner=exclude","excerpt":"Booking Holdings Inc. filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"BKNG annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001075531&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"BKNG quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001075531&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"BKNG proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001075531&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"BKNG investor relations","meta":"Company primary materials","href":"https://ir.bookingholdings.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"BKNG official newsroom","meta":"Company announcements","href":"https://www.bookingholdings.com/news/","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001075531&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001075531&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001075531&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001075531&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://ir.bookingholdings.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
